def draw_Eyebrow(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, '基础', '基础', 0, None, True)
    if g0 is not None:
        kit.texture(g0, p, 'p_BaseMap', 'Albedo', 't_BaseMap', 'o_BaseMap')
        kit.texture(g0, p, 'p_BumpMap', 'Normal Map', None, None)
        kit.texture(g0, p, 'p_EmissionMap', 'Emission', None, None)
        kit.texture(g0, p, 'p_RMOSMap', 'RMOS Map (R=Rough G=Metal B=Occ A=Spec)', None, None)
        kit.prop(g0, p, 'p_BaseColor', 'Color')
        kit.prop(g0, p, 'p_BumpScale', 'Scale')
        kit.prop(g0, p, 'p_RoughnessIntensity', 'Roughness Intensity')
        kit.prop(g0, p, 'p_MetallicIntensity', 'Metallic Intensity')
        kit.prop(g0, p, 'p_SpecularIntensity', 'Specular Intensity')
        kit.prop(g0, p, 'c_SurfaceType', 'Surface Type')
        kit.prop(g0, p, 'p_UseRMOSMap', 'Use RMOS Map')
        kit.prop(g0, p, 'p_UseBumpMap', 'Use NormalMap')
        kit.prop(g0, p, 'p_UseEmission', 'Use Emission')
        kit.prop(g0, p, 'p_EmissionColor', 'Emission Color')
        kit.prop(g0, p, 'p_OutlineTintEnable', 'Outline Tint Color Enable')
        kit.prop(g0, p, 'p_OutlineTintColor', 'Outline Tint Color')
        kit.prop(g0, p, 'c_BackFaceNormalFlip', 'Back Face Normal Flip')
        kit.prop(g0, p, 'p_FBXRotationFix', 'FBX -90 Z Rotation Fix (OTW col0/col1 swap)')
        kit.prop(g0, p, 'p_ExposureWithMiscParams', 'Exposure (y = post exposure)')
        kit.prop(g0, p, 'p_VFXParams0', 'VFX Params0 (xyz = 角色位, w = 时间)')
    g1 = kit.group(root, p, 'PBR 基础', 'PBR 基础', 0, None, True)
    if g1 is not None:
        kit.texture(g1, p, 'p_MetallicGlossMap', 'RGBA:Metal,Spec,Shadow,Smooth', None, None)
        kit.prop(g1, p, 'p_UseMetallicGlossMap', 'Use MetallicGlossMap')
        kit.prop(g1, p, 'p_Metallic', 'Metallic')
        kit.prop(g1, p, 'p_Specular', 'Specular Scale')
        kit.prop(g1, p, 'p_Smoothness', 'Smoothness')
    g2 = kit.group(root, p, '自发光', '自发光', 0, None, True)
    if g2 is not None:
        kit.prop(g2, p, 'p_EmissionBrightness', 'Emission Brightness')
    g3 = kit.group(root, p, 'Ramp', 'Ramp', 0, None, True)
    if g3 is not None:
        kit.texture(g3, p, 'p_DiffRampMap', 'Diffuse Ramp', None, None)
        kit.prop(g3, p, 'p_UseDiffRampMap', 'Diffuse Ramp')
    g4 = kit.group(root, p, '阴影色', '阴影色', 0, None, True)
    if g4 is not None:
        kit.texture(g4, p, 'p_ShadowLutTex', 'Shadow Color Lut', None, None)
        kit.prop(g4, p, 'p_UseShadowLutTex', 'Use Shadow Color LUT Tex')
        kit.prop(g4, p, 'p_ShadowColorBrightness', 'Shadow Color Brightness')
        kit.prop(g4, p, 'p_ShadowColorSaturation', 'Shadow Color Saturation')
    g5 = kit.group(root, p, '眼睛 Matcap', '眼睛 Matcap', 0, None, True)
    if g5 is not None:
        kit.texture(g5, p, 'p_MatcapTex', 'Matcap', None, None)
        kit.prop(g5, p, 'p_UseMatcap', 'Use Matcap')
        kit.prop(g5, p, 'p_EyeHighLight', 'Eye High Light')
        kit.prop(g5, p, 'p_MatcapNormalScale', 'Matcap Normal Scale')
        kit.prop(g5, p, 'p_MatcapColor', 'Matcap Color')
        kit.prop(g5, p, 'p_EyeHighLightColor', 'High Light Color')
        kit.prop(g5, p, 'p_EyeScatteringColor', 'Scattering Color')
        kit.prop(g5, p, 'p_EyeTintColor', 'Eye Tint Color')
    g6 = kit.group(root, p, '视差', '视差', 0, None, True)
    if g6 is not None:
        kit.prop(g6, p, 'p_ParallaxScale', 'Parallax Scale')
    g7 = kit.group(root, p, '捏人染色', '捏人染色', 0, 'p_AvatarCustomizeEnable', True)
    if g7 is not None:
        pass
    g8 = kit.group(root, p, '描边', '描边', 0, None, True)
    if g8 is not None:
        kit.prop(g8, p, 'p_OutlineColorBrightness', 'Outline Color Brightness')
        kit.prop(g8, p, 'p_OutlineColorSaturation', 'Outline Color Saturation')
    g9 = kit.group(root, p, 'State', 'State', 0, None, True)
    if g9 is not None:
        kit.prop(g9, p, 'c_Cull', 'Render Face')

def draw_Eyes(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, 'Albedo', 'Albedo', 1, None, True)
    if g0 is not None:
        kit.prop(g0, p, 'p_BaseColor', 'Color')
        kit.texture(g0, p, 'p_BaseMap', 'Albedo', 't_BaseMap', 'o_BaseMap')
        kit.prop(g0, p, 'c_SurfaceType', 'Surface Type')
        kit.prop(g0, p, 'c_Cull', 'Render Face')
        if not (p.p_Cull == 2.0):
            kit.prop(g0, p, 'c_BackFaceNormalFlip', 'Back Face Normal Flip')
        g1 = kit.group(g0, p, 'Albedo/Shadow_Color_Input', 'Shadow Color Input', 6, None, False)
        if g1 is not None:
            kit.prop(g1, p, 'p_UseShadowLutTex', 'Use Shadow Color LUT Tex')
            if not (not p.p_UseShadowLutTex):
                kit.texture(g1, p, 'p_ShadowLutTex', 'Shadow Color Lut', None, None)
            if not (p.p_UseShadowLutTex):
                kit.prop(g1, p, 'p_ShadowColorBrightness', 'Shadow Color Brightness')
            if not (p.p_UseShadowLutTex):
                kit.prop(g1, p, 'p_ShadowColorSaturation', 'Shadow Color Saturation')
        g2 = kit.group(g0, p, 'Albedo/Avatar_System_Input', 'Avatar System Input', 6, 'p_AvatarCustomizeEnable', False)
        if g2 is not None:
            kit.prop(g2, p, 'p_EyeTintColor', 'Eye Tint Color')
    g3 = kit.group(root, p, 'PBRInput', 'PBRInput', 2, None, True)
    if g3 is not None:
        kit.prop(g3, p, 'p_UseEmission', 'Use Emission')
        if not (not p.p_UseEmission):
            kit.prop(g3, p, 'p_EmissionColor', 'Emission Color')
        if not (not p.p_UseEmission):
            kit.prop(g3, p, 'p_EmissionBrightness', 'Emission Brightness')
        if not (not p.p_UseEmission):
            kit.texture(g3, p, 'p_EmissionMap', 'Emission', None, None)
        g4 = kit.group(g3, p, 'PBRInput/Diffuse_Ramp', 'Diffuse Ramp', 4, 'p_UseDiffRampMap', False)
        if g4 is not None:
            kit.texture(g4, p, 'p_DiffRampMap', 'Diffuse Ramp', None, None)
        g5 = kit.group(g3, p, 'PBRInput/Use_Matcap', 'Use Matcap', 6, 'p_UseMatcap', False)
        if g5 is not None:
            kit.texture(g5, p, 'p_MatcapTex', 'Matcap', None, None)
            kit.prop(g5, p, 'p_MatcapNormalScale', 'Matcap Normal Scale')
            kit.prop(g5, p, 'p_MatcapColor', 'Matcap Color')
            kit.separator(g5)
            kit.prop(g5, p, 'p_ParallaxScale', 'Parallax Scale')
        g6 = kit.group(g3, p, 'PBRInput/Eye_High_Light', 'Eye High Light', 4, 'p_EyeHighLight', False)
        if g6 is not None:
            kit.prop(g6, p, 'p_EyeHighLightColor', 'High Light Color')
            kit.prop(g6, p, 'p_EyeScatteringColor', 'Scattering Color')
    u7 = kit.group(root, p, 'unimplemented', '未实现功能(仅记录值,暂无效果)', 0, None, True)
    if u7 is not None:
        kit.label(u7, 'Albedo')
        if not (p.p_SurfaceType == 0.0):
            kit.prop(u7, p, 'c_BlendMode', 'Blend Type')
        if not (p.p_SurfaceType == 0.0):
            kit.prop(u7, p, 'c_TransparentDepthWrite', 'Transparent Depth Write')
        kit.label(u7, 'UseVATMap')
        kit.prop(u7, p, 'p_UseVATMap', 'UseVATMap')
        kit.texture(u7, p, 'p_AnimationTexture', 'Animation Texture', None, None)
        kit.prop(u7, p, 'p_DebugVATFrameIndex', 'DebugVATFrame')
        kit.prop(u7, p, 'p_VATFrameIndex', 'VAT Frame Index')
        kit.label(u7, 'NPR Option')
        kit.prop(u7, p, 'c_PreZStencilRefOption', 'Draw Over Hair')
        kit.label(u7, 'Alpha Test')
        kit.prop(u7, p, 'p_EnableAlphaTest', 'Alpha Test')
        kit.prop(u7, p, 'p_AlphaClipThreshold', 'Clip Threshold')
